// RawDenoiseTilingTests.swift
// The raw denoiser's tiler against the Python it was ported from.
//
// Every expectation here is a literal produced by running the REAL
// `Engine.denoise_packed` (Denoise/scripts/gen_swift_fixtures_tiling.py), not a value
// re-derived from the Swift: a port checked against itself agrees with any bug it has.
// The plan cases include the camera sizes that matter (A7 IV and GX85 packed frames),
// the tile-boundary sizes where the origin clamp kicks in (1024, 1025), and frames
// smaller than one tile, where the padding and flat-weight branches run.

import XCTest
@testable import LumenCore

final class RawDenoiseTilingTests: XCTestCase {

    typealias Fx = RawDenoiseTilingFixtures

    // MARK: - Tile plan

    func testTilePlansMatchInferPy() {
        XCTAssertFalse(Fx.plans.isEmpty)
        for c in Fx.plans {
            let plan = RawDenoiseTilePlan(width: c.width, height: c.height, tile: c.tile, overlap: c.overlap)
            let got = plan.tiles.map { [$0.y0, $0.x0, $0.height, $0.width, $0.padBottom, $0.padRight] }
            XCTAssertEqual(got, c.tiles, "plan \(c.width)x\(c.height) tile \(c.tile) ov \(c.overlap)")
            for t in plan.tiles {
                XCTAssertEqual(t.paddedHeight % 16, 0)
                XCTAssertEqual(t.paddedWidth % 16, 0)
            }
        }
    }

    func testEmptyImageHasNoTiles() {
        XCTAssertTrue(RawDenoiseTilePlan(width: 0, height: 10).tiles.isEmpty)
        XCTAssertEqual(RawDenoiseTiler.run(packed: [], width: 0, height: 0) { t, _, _ in t }, [])
    }

    // MARK: - Feather weights

    func testFeatherWeightsMatchInferPy() {
        XCTAssertFalse(Fx.feathers.isEmpty)
        for c in Fx.feathers {
            let t = RawDenoiseTilePlan.Tile(y0: c.tile0[0], x0: c.tile0[1], height: c.tile0[2],
                                            width: c.tile0[3], padBottom: c.tile0[4], padRight: c.tile0[5])
            let (wy, wx) = RawDenoiseTiler.featherWeights(tile: t, imageWidth: c.width, imageHeight: c.height,
                                                          tileSize: c.tile, overlap: c.overlap)
            // Exact: the ramp is a handful of f32 divisions, identical on both sides.
            XCTAssertEqual(wy, c.wy, "wy for tile \(c.tile0) of \(c.width)x\(c.height)")
            XCTAssertEqual(wx, c.wx, "wx for tile \(c.tile0) of \(c.width)x\(c.height)")
        }
    }

    // MARK: - Reflect padding

    func testReflectPadMatchesNumpyReflect() {
        XCTAssertFalse(Fx.reflect.isEmpty)
        for c in Fx.reflect {
            let a = (0..<(c.channels * c.height * c.width)).map { Float($0) }
            let got = RawDenoiseTiler.reflectPad(planes: a, channels: c.channels, height: c.height, width: c.width,
                                                 padBottom: c.padBottom, padRight: c.padRight)
            XCTAssertEqual(got, c.output, "reflect \(c.channels)x\(c.height)x\(c.width) + (\(c.padBottom), \(c.padRight))")
        }
    }

    // MARK: - Tiled run

    /// A deterministic frame of k/1024 values (the same hash the generator uses).
    private func fixtureInput(count: Int) -> [Float] {
        (0..<count).map { i in Float(Double((i &* 2654435761) % 1021) / 1024.0) }
    }

    func testIdentityBodyReturnsInput() {
        // Small-tile seams, a sub-tile frame, and the real default tile on a frame that
        // needs two clamped tiles per axis.
        let cases: [(c: Int, h: Int, w: Int, tile: Int, ov: Int)] = [
            (4, 45, 70, 32, 8), (4, 13, 30, 24, 4), (4, 7, 5, 1024, 64), (4, 1100, 1300, 1024, 64),
        ]
        for k in cases {
            let p = fixtureInput(count: k.c * k.h * k.w)
            var calls = 0
            let out = RawDenoiseTiler.run(packed: p, width: k.w, height: k.h, tile: k.tile, overlap: k.ov) { t, ph, pw in
                calls += 1
                XCTAssertEqual(t.count, k.c * ph * pw)
                XCTAssertEqual(ph % 16, 0); XCTAssertEqual(pw % 16, 0)
                return t
            }
            XCTAssertEqual(calls, RawDenoiseTilePlan(width: k.w, height: k.h, tile: k.tile, overlap: k.ov).tiles.count)
            XCTAssertEqual(out.count, p.count)
            let err = zip(out, p).map { abs($0 - $1) }.max() ?? 0
            XCTAssertLessThanOrEqual(err, 1e-6, "identity drifted on \(k.w)x\(k.h)")
        }
    }

    /// Mirror of the generator's BlurNet: 3×3 clamp-to-edge box over the padded tile,
    /// summed in the same (dy, dx) order in f32, plus 0.01·call·(channel+1).
    private func blurBody(channels: Int) -> ([Float], Int, Int) -> [Float] {
        var call = 0
        return { t, h, w in
            call += 1
            var o = [Float](repeating: 0, count: t.count)
            for c in 0..<channels {
                let bias = Float(0.01 * Double(call) * Double(c + 1))
                for y in 0..<h {
                    for x in 0..<w {
                        var s: Float = 0
                        for dy in -1...1 {
                            let yy = min(max(y + dy, 0), h - 1)
                            for dx in -1...1 {
                                let xx = min(max(x + dx, 0), w - 1)
                                s += t[(c * h + yy) * w + xx]
                            }
                        }
                        o[(c * h + y) * w + x] = s / 9 + bias
                    }
                }
            }
            return o
        }
    }

    func testBlurBodyMatchesInferPySeamBlending() throws {
        XCTAssertFalse(Fx.parity.isEmpty)
        for c in Fx.parity {
            let expected = try decodeFloats(c.output)
            XCTAssertEqual(expected.count, c.channels * c.height * c.width)
            let p = fixtureInput(count: c.channels * c.height * c.width)
            var calls = 0
            let body = blurBody(channels: c.channels)
            let out = RawDenoiseTiler.run(packed: p, width: c.width, height: c.height,
                                          tile: c.tile, overlap: c.overlap) { t, h, w in
                calls += 1
                return body(t, h, w)
            }
            XCTAssertEqual(calls, c.calls)
            var worst: Float = 0, worstAt = 0
            for i in 0..<out.count where abs(out[i] - expected[i]) > worst {
                worst = abs(out[i] - expected[i]); worstAt = i
            }
            XCTAssertLessThanOrEqual(worst, 1e-6,
                                     "\(c.channels)x\(c.height)x\(c.width) tile \(c.tile): worst at \(worstAt)")
        }
    }

    func testBodyErrorPropagates() {
        struct Boom: Error {}
        XCTAssertThrowsError(try RawDenoiseTiler.run(packed: [Float](repeating: 0, count: 4 * 20 * 20),
                                                     width: 20, height: 20, tile: 32, overlap: 8) { _, _, _ in
            throw Boom()
        })
    }

    private func decodeFloats(_ b64: String) throws -> [Float] {
        let data = try XCTUnwrap(Data(base64Encoded: b64))
        return data.withUnsafeBytes { raw in
            (0..<(data.count / 4)).map { Float(bitPattern: UInt32(littleEndian: raw.loadUnaligned(fromByteOffset: $0 * 4, as: UInt32.self))) }
        }
    }

    // MARK: - Strength blend

    func testBlendEndpointsAreExact() {
        let d: [Float] = [0.1, 0.5, 0.9, 0]
        let o: [Float] = [0.3, 0.2, 0.7, 1]
        XCTAssertEqual(RawDenoiseTiler.blend(denoised: d, original: o, strength: 1), d)
        XCTAssertEqual(RawDenoiseTiler.blend(denoised: d, original: o, strength: 0), o)
    }

    func testBlendIsLinearMix() {
        let d: [Float] = [0.1, 0.5, 0.9, 0]
        let o: [Float] = [0.3, 0.2, 0.7, 1]
        // numpy: float32(0.7)·d + float32(1 − 0.7)·o, with 1 − 0.7 taken in double.
        let got = RawDenoiseTiler.blend(denoised: d, original: o, strength: 0.7)
        for i in 0..<d.count {
            let want = Float(0.7) * d[i] + Float(1 - 0.7) * o[i]
            XCTAssertEqual(got[i], want, "element \(i)")
        }
        XCTAssertEqual(got[3], Float(1 - 0.7))
    }
}

